local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local SpriteRenderer = CS.UnityEngine.SpriteRenderer
local ImageComp = CS.UnityEngine.UI.Image
local KTool = CS.Engine.Lib.KTool
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine'

---@class ScreenTurningEffect : BaseEffect
local ScreenTurningEffect = Class("ScreenTurningEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")


function ScreenTurningEffect:__init()
    self.TargetColor = nil
    self.StartColor = nil
    self.Duration = 2
    self.PrevColor = nil
    self.Tween = nil
    self._isFinish = nil
    self._isIn = nil
end

function ScreenTurningEffect:__delete()
    self.TargetColor = nil
    self.StartColor = nil
    self.Duration = nil
    self.PrevColor = nil
    self.Tween = nil
    self._isFinish = nil
    self._isIn = nil
end

function ScreenTurningEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
    if parameters.screenAnim == NewChapterConstants.ScreenEffect.FullBlackFadeIn
            or parameters.screenAnim == NewChapterConstants.ScreenEffect.CgBlackFadeIn then
        self.TargetColor = Color.New(0,0,0,0)
        self.StartColor = Color.New(0,0,0,1)
        self._isIn = false
    elseif parameters.screenAnim == NewChapterConstants.ScreenEffect.FullBlackFadeOut
            or parameters.screenAnim == NewChapterConstants.ScreenEffect.CgBlackFadeOut then
        self.TargetColor = Color.New(0,0,0,1)
        self.StartColor = Color.New(0,0,0,0)
        self._isIn = true
    end
end

function ScreenTurningEffect:StartEffect(object)
    base.StartEffect(self, object)

    if not KTool.IsActiveInHierarchy(object.gameObject) then
        KTool.SetActive(object.gameObject, true)
        KTool.SetActive(object.transform.parent, true)
    end

    local render =  object.gameObject:GetComponent(typeof(ImageComp))
    if isNull(render) then
        return
    end
    self.PrevColor = render.color
    --render.color = self.Color
    self._isFinish = not self._isIn
    render.color = self.StartColor
    --printInfo(self.TargetColor)
    if self._isIn then
        self.Tween = render:DOColor(self.TargetColor, self.Duration):OnComplete(function()
            self._isFinish = true
        end)
    end
end

function ScreenTurningEffect:IsFinish()
    base.IsFinish(self)
    return self._isFinish
end

function ScreenTurningEffect:EndEffect(object)
    base.EndEffect(self, object)
    
end

function ScreenTurningEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    self:RemoveCo()
    if  KTool.IsNull(object) then
        return
    end

    local render =  object.gameObject:GetComponent(typeof(ImageComp))
    if isNull(render) then
        return
    end

    if not self._isIn then
        self.co = cs_coroutine.start(function()
            local wait = true
            self.Tween = render:DOColor(self.TargetColor, self.Duration):OnComplete(function()
                wait = false
            end)

            while wait do
                coroutine.yield()
            end

            if KTool.IsActiveInHierarchy(object.gameObject) then
                KTool.SetActive(object.gameObject, false)
                KTool.SetActive(object.transform.parent, false)
            end

            render.color = self.PrevColor

        end)
        return self.co
    else
        if KTool.IsActiveInHierarchy(object.gameObject) then
            KTool.SetActive(object.gameObject, false)
            KTool.SetActive(object.transform.parent, false)
        end
        render.color = self.PrevColor
    end
end

function ScreenTurningEffect:RemoveCo()
    if not isNull(self.Tween) then
        self.Tween:Kill()
        self.Tween = nil
    end

    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
end

return ScreenTurningEffect